int monitor::process_ordered_line(tsv::ctx &tc, std::string_view line) {
	tsv::row_t row;
	tsv::split(line, row);

	const packet_context packet = make_packet_context(tc, row);
	if(m_cfg.analysis_enabled) {
		// Pre-roll warms tshark reassembly; STM counters/events start at A.
		if((m_cfg.analysis_from && packet.time_epoch < *m_cfg.analysis_from) ||
		   (m_cfg.analysis_to && packet.time_epoch >= *m_cfg.analysis_to)) {
			m_pipeline_progress->record_processed_packet(0.0);
			return 0;
		}
		const auto boundary = m_second_boundary.update(packet.time_epoch);
		if(boundary.changed && m_last_analysis_packet) {
			write_second_boundary_outputs(m_last_analysis_packet->time_epoch, *m_last_analysis_packet);
		}
	}
	if(packet.dispatch_proto_changed()) {
		trace(4, "monitor: effective proto %s -> %s method=%s uri=%s status=%s",
		      packet.proto.c_str(),
		      packet.dispatch_proto.c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.method)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.uri)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.status_code)).c_str());
	}

	m_interfaces->observe(packet.interface_id, packet.interface_name);

	m_streams->process_packet(tc, row, packet);

	if(m_cfg.analysis_enabled) {
		m_last_analysis_packet = packet;
	}
	else {
		auto br = m_second_boundary.update(packet.time_epoch);
		if(br.changed) write_second_boundary_outputs(tc.r.com.time_epoch, packet);
	}

	m_pipeline_progress->record_processed_packet(packet.time_epoch);
	return 0;
}

