}

void monitor::on_tsv_read_begin() {
	m_pipeline_progress->timing().begin(pipeline_timing::stage::tsv_read);
}

void monitor::on_tsv_read_end() {
	m_pipeline_progress->timing().end();
}

void monitor::flush_reorder_ready() {
	if(!m_reorder_tsv_ctx) {
		return;
	}
	m_reorder.flush_ready([this](std::string_view ordered_line) {
		process_ordered_line(*m_reorder_tsv_ctx, ordered_line);
	});
}

void monitor::flush_reorder_all() {
	auto timing = m_pipeline_progress->timing().measure(pipeline_timing::stage::analysis);
	if(!m_reorder_tsv_ctx) {
		return;
	if(m_input_gap_pending) {
		// append_metrics consumes the window counters. This window includes an
		// unobserved interval; do not journal it or use it for rule evaluation.
		build_metrics_root(now, packet);
		m_input_gap_pending = false;
		return;
	}
	update_second_boundary_state(now);
	auto metrics_root = build_metrics_root(now, packet);
	evaluate_alerts(now, metrics_root);
	auto journal = m_pipeline_progress->timing().measure(pipeline_timing::stage::journal);
	m_logs->append_metrics_snapshot(metrics_root);
}

