}

/** Historical events, rather than today's configured rules, determine graph ownership. */
export function chartAlertEventsForMetric(events: EventLogItem[], metricKey: string, target: ChartAlertEventTarget) {
  return events.filter(event => {
    const detail = event.detail;
    if (!detail || typeof detail !== "object" || Array.isArray(detail) || !("metric" in detail)
      || typeof detail.metric !== "string" || metricKeyForAlert(detail.metric) !== metricKey) return false;
    if (target.kind === "interface") return event.interfaceId === target.interfaceId && !event.streamKey && !event.flowKey;
    if (event.streamKey !== target.streamKey) return false;
    return target.kind === "flow" ? event.flowKey === target.flowKey : !event.flowKey && event.scope !== "flow";
  });
}

